begin;
set local lock_timeout = '5s';
create table public.bloques_web (
 id text primary key check (id ~ '^[a-z0-9-]+$'),
 grupo text not null,
 etiqueta text not null,
 titulo text not null check (length(btrim(titulo)) between 1 and 200),
 cuerpo text not null check (length(btrim(cuerpo)) between 1 and 6000),
 enlace_texto text not null default '' check (length(enlace_texto)<=100),
 enlace_url text not null default '' check (length(enlace_url)<=2048 and (enlace_url='' or enlace_url ~ '^https://' or enlace_url ~ '^/[^/]')),
 orden integer not null default 0
);
alter table public.bloques_web enable row level security;
revoke all on public.bloques_web from public, anon, authenticated;
grant select on public.bloques_web to anon, authenticated;
grant update(titulo,cuerpo,enlace_texto,enlace_url) on public.bloques_web to authenticated;
create policy lectura on public.bloques_web for select to anon,authenticated using(true);
create policy mantenimiento on public.bloques_web for update to authenticated using ((select renting_privado.es_admin())) with check ((select renting_privado.es_admin()));

El equipo confirmará la documentación, edad y experiencia de conducción requeridas según la unidad y el servicio. Envíe documentos únicamente por el canal que le indiquemos.','','',1);

Para movilidad empresarial, indique cuántas unidades necesita y los lugares de operación. La duración y las condiciones se acuerdan antes de contratar.','','',2);

Revise también la tarifa, kilometraje, combustible, coberturas, exclusiones y entrega de la unidad. Una consulta no confirma una reserva ni genera un pago.','Consultar requisitos y garantía','',3);

Una consulta por correo, teléfono o WhatsApp no se presenta aquí como sustituto del Libro de Reclamaciones.','Consultar canal de atención','/contacto/',30);

Los datos que envíe se solicitan para atender su consulta y coordinar la cotización. No incluya números de tarjeta, documentos de identidad ni información que no sea necesaria para describir el servicio.','','',38);
alter table public.configuracion_web
 add column email text not null default 'rentingcaraym@gmail.com',
 add column email_administracion text not null default 'administracion@grupoaym.com',
 add column direccion text not null default 'Av. Santiago de Surco 3573, Santiago de Surco 15038',
 add column grupo_url text not null default 'https://grupoaym.com/';
commit;
