insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-header','Alquiler','Encabezado','Prepare su alquiler con tranquilidad','Información para comenzar. Las condiciones se confirman en su propuesta.','','',0);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-requirements','Alquiler','Requisitos','Documentación en regla','Tenga a mano su documento de identidad vigente y, si conducirá, una licencia vigente que corresponda al vehículo. Para empresas, prepare el RUC y los datos de la persona responsable.
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-duration','Alquiler','Duración','El tiempo que necesita','Cuéntenos si busca una unidad por días, semanas o meses, las fechas previstas y el uso que le dará. Evaluaremos la disponibilidad y una propuesta para su solicitud.
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-guarantee','Alquiler','Garantía','Garantía y condiciones claras','Consulte por WhatsApp el importe y la modalidad de garantía, así como las condiciones y plazos de devolución aplicables a su alquiler.
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-rates','Alquiler','Tarifas','Tarifas según su solicitud','Solicite una cotización indicando el modelo, las fechas y el recorrido previsto. Confirme el importe total, los conceptos incluidos, las formas de pago y cualquier cargo adicional antes de contratar. Las tarifas se acuerdan en la propuesta; enviar una consulta no realiza un pago.','Consultar tarifas','/contacto/',4);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('rental-coverage','Alquiler','Coberturas','Revise las coberturas','Pida al equipo el detalle de las coberturas aplicables a la unidad, sus límites, exclusiones y deducibles, si corresponden. Confirme también el uso autorizado, el kilometraje y las indicaciones ante un incidente. No asuma una cobertura que no figure en las condiciones del servicio.','Consultar coberturas','/contacto/',5);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-header','Preguntas frecuentes','Encabezado','Preguntas frecuentes sobre el alquiler de autos','Estamos para ayudarle a elegir el servicio adecuado.','','',6);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-01','Preguntas frecuentes','¿Cómo solicito una cotización?','¿Cómo solicito una cotización?','Elija un modelo o servicio y pulse Cotizar. También puede completar el formulario de contacto para preparar un mensaje y enviarlo por WhatsApp.','','',7);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-02','Preguntas frecuentes','¿Cuáles son los requisitos para alquilar un auto en Lima?','¿Cuáles son los requisitos para alquilar un auto en Lima?','Prepare su documento de identidad vigente y la licencia vigente de quien conducirá. Para empresas, indique el RUC y un contacto responsable. El equipo confirmará los requisitos específicos, la documentación y las condiciones de garantía según el servicio.','','',8);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-03','Preguntas frecuentes','¿Cuánto es la garantía y cuándo se devuelve?','¿Cuánto es la garantía y cuándo se devuelve?','Consulte por WhatsApp el importe, la modalidad y las condiciones y plazos de devolución. Estos puntos deben quedar definidos en su propuesta y contrato antes de confirmar el alquiler.','','',9);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-04','Preguntas frecuentes','¿Puedo solicitar alquiler por días, semanas o meses?','¿Puedo solicitar alquiler por días, semanas o meses?','Indique las fechas y la duración que necesita. Nuestro equipo evaluará disponibilidad y condiciones para su solicitud, tanto personal como empresarial.','','',10);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-05','Preguntas frecuentes','¿Pueden entregar el vehículo y emitir un comprobante?','¿Pueden entregar el vehículo y emitir un comprobante?','Indique el lugar de entrega y recojo, y los datos de facturación al cotizar. Confirme con el equipo el comprobante correspondiente, las opciones de entrega y cualquier costo adicional antes de contratar.','','',11);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-06','Preguntas frecuentes','¿Qué incluye la tarifa y el seguro?','¿Qué incluye la tarifa y el seguro?','La tarifa, el kilometraje, las coberturas y las formas de pago se detallan en la propuesta. Consúltelos antes de confirmar el alquiler.','','',12);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-07','Preguntas frecuentes','¿Puedo alquilar con chofer o sin chofer?','¿Puedo alquilar con chofer o sin chofer?','Indique si necesita conductor u operador al solicitar la cotización. Nuestro equipo confirmará las opciones para su servicio.','','',13);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-08','Preguntas frecuentes','¿Atienden proyectos fuera de Lima?','¿Atienden proyectos fuera de Lima?','Indique el lugar de obra o el origen y destino de la carga. La cobertura y movilización se evalúan para cada solicitud.','','',14);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('faq-09','Preguntas frecuentes','¿Enviar una consulta confirma mi reserva?','¿Enviar una consulta confirma mi reserva?','La solicitud inicia una conversación. La disponibilidad, las condiciones y la contratación se coordinan directamente con nuestro equipo.','','',15);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('why-header','Ventajas','Encabezado','¿Por qué alquilar con Renting Car A&M?','Conozca nuestra atención y servicios.','Conozca Renting Car A&M','/nosotros/',16);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('why-01','Ventajas','Dos líneas de servicio','Dos líneas de servicio','Vehículos livianos, maquinaria y transporte de carga en un mismo lugar.','','',17);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('why-02','Ventajas','Taller propio en Surco','Taller propio en Surco','Contamos con un taller de reparación en nuestra sede de Santiago de Surco.','','',18);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('why-03','Ventajas','Personas y empresas','Personas y empresas','Cuéntenos su necesidad de movilidad o el trabajo que requiere su proyecto.','','',19);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('why-04','Ventajas','Atención directa','Atención directa','Visítenos en Surco o converse con nuestro equipo por WhatsApp.','','',20);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('steps-header','Cómo trabajamos','Encabezado','Pasos para alquilar su vehículo','Coordinamos los detalles de su servicio con atención personalizada.','','',21);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('step-01','Cómo trabajamos','Paso 1','Elija su vehículo o servicio','Explore nuestra flota liviana y las opciones de maquinaria y transporte.','','',22);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('step-02','Cómo trabajamos','Paso 2','Solicite su cotización','Indique fechas, ubicación y necesidades para recibir una propuesta.','','',23);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('step-03','Cómo trabajamos','Paso 3','Coordine documentos y contrato','Revise con nuestro equipo los requisitos, las condiciones y la disponibilidad.','','',24);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('step-04','Cómo trabajamos','Paso 4','Reciba su unidad','Una vez acordado el servicio, coordine la entrega o el inicio del trabajo.','','',25);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('closing','Contacto y llamados','Invitación a cotizar','¿Necesita un vehículo o equipo?','Solicite una cotización con los detalles de su servicio.','Solicitar cotización','/contacto/#cotizacion',26);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('vehicle-conditions','Alquiler','Condiciones en las fichas','Condiciones de su alquiler','La propuesta detalla tarifa, requisitos, garantía, kilometraje y coberturas. Confirme disponibilidad y condiciones con nuestro equipo.','Consultar condiciones','/como-funciona/',27);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('complaints-header','Reclamaciones','Encabezado','Libro de Reclamaciones','Información del canal de atención.','','',28);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('complaints-status','Reclamaciones','Estado del registro','Registro virtual pendiente de habilitación','El Libro de Reclamaciones virtual aún no está habilitado en esta web. Esta página no registra una reclamación ni emite una constancia.','','',29);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('complaints-channel','Reclamaciones','Canal y enlace al Libro','Consulte el canal de registro','Para consultar por el canal de registro disponible, contacte a Renting Car A&M mediante los datos de atención indicados en esta página.
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('terms-header','Condiciones','Encabezado','Condiciones de cotización','Revise las condiciones de su servicio con nuestro equipo antes de confirmar.','','',31);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('terms-01','Condiciones','Solicitud de información','Solicitud de información','El catálogo y el formulario permiten solicitar una propuesta. Preparar o enviar un mensaje no confirma una reserva ni realiza un pago.','','',32);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('terms-02','Condiciones','Disponibilidad y características','Disponibilidad y características','Solicite la confirmación del modelo, versión, características y disponibilidad de la unidad para sus fechas. Las fotografías identificadas como referenciales no corresponden a la unidad ofrecida.','','',33);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('terms-03','Condiciones','Condiciones de cada servicio','Condiciones de cada servicio','La propuesta y el contrato deben precisar tarifa, garantía, documentos requeridos, coberturas, kilometraje, entrega y devolución. Para maquinaria y transporte, consulte también operador o conductor, combustible, movilización y alcance del trabajo.','','',34);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('terms-04','Condiciones','Documento pendiente','Documento pendiente','Los términos y condiciones completos de alquiler están pendientes de aprobación por A&M. Esta página contiene información sobre la solicitud de cotización y no sustituye el contrato del servicio.','','',35);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-header','Privacidad','Encabezado','Privacidad de su solicitud','Cómo funciona el formulario de cotización de esta web.','','',36);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-01','Privacidad','Datos que usted decide compartir','Datos que usted decide compartir','El formulario le permite preparar una consulta con su nombre, teléfono, correo opcional, empresa y RUC opcionales, fechas, ubicación y descripción del servicio. Estos datos se incorporan al mensaje que usted revisa antes de enviarlo.','','',37);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-02','Privacidad','Preparación y envío del mensaje','Preparación y envío del mensaje','El formulario prepara el resumen en su navegador. Esta web no envía el formulario a un servidor ni guarda sus datos en una base de datos. Al pulsar «Abrir WhatsApp», el mensaje se comparte con WhatsApp mediante un enlace. Para que Renting Car A&M lo reciba, debe enviarlo dentro de esa aplicación.
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-03','Privacidad','Servicios externos','Servicios externos','Los enlaces de WhatsApp, correo, Google Maps y Waze abren servicios de terceros. El mapa integrado y las fuentes de Google también pueden establecer conexiones con sus proveedores. El uso de esos servicios se rige por sus propias condiciones de privacidad.','','',39);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-04','Privacidad','Consultas sobre sus datos','Consultas sobre sus datos','Puede comunicarse con Renting Car A&M por los canales de atención indicados en esta página para consultar sobre los datos que ha compartido.','','',40);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('privacy-05','Privacidad','Alcance de esta información','Alcance de esta información','Este aviso describe el funcionamiento actual del sitio. La política completa de la empresa, con identificación de la entidad responsable y condiciones de tratamiento, está pendiente de validación por A&M.','','',41);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('footer-summary','Contacto y llamados','Presentación del pie','Renting Car A&M','Alquiler de autos, camionetas y maquinaria pesada en Santiago de Surco, Lima.','','',42);
insert into public.bloques_web(id,grupo,etiqueta,titulo,cuerpo,enlace_texto,enlace_url,orden) values ('contact-intro','Contacto y llamados','Tarjeta de contacto','Alquiler de autos en Santiago de Surco: visítenos','Vehículos, maquinaria, transporte y taller de reparación.','','',43);
